/* ---------- asana library: poses, sequences per book section ---------- */
window.LIB=LIB;
(function(){
  const M=LIBMETA,secRu=window.SECRU||{};
  const TYPE=[['standing one-legged balance','баланс на одной ноге'],['one-legged balance','баланс на одной ноге'],['arm balance','баланс на руках'],['forward bend','наклон вперёд'],['side bend','боковой наклон'],['backbend','прогиб'],['twist','скручивание'],['binding','захват'],['inversion','перевёрнутая'],['standing','стоя'],['seated','сидя'],['supine','лёжа на спине'],['prone','лёжа на животе'],['kneeling','на коленях'],['balance','баланс'],['core','кор'],['hip opener','раскрытие таза'],['restorative','восстанавливающая'],['quadruped','на четвереньках'],['squat','присед'],['lunge','выпад'],['mild','мягкий']];
  const trType=s=>{let t=(s||'').toLowerCase();for(const [a,b] of TYPE)t=t.split(a).join(b);return t;};
  const DR=[['Nasagrai','кончик носа'],['Nasagre','кончик носа'],['Bhrumadhye','межбровье'],['Ajna Chakra','межбровье'],['Hastagrai','кисть'],['Hastagre','кисть'],['Padayoragrai','пальцы ног'],['Padayoragre','пальцы ног'],['Nabhi','пупок'],['Angushtamadhye','большие пальцы рук'],['Angushta Ma Dyai','большие пальцы рук'],['Parshva Drishti','в сторону'],['Urdhva','вверх'],['Antara Drishti','вверх']];
  const trDr=s=>{const out=[];for(const [a,b] of DR)if((s||'').includes(a)&&!out.includes(b))out.push(b);return out.join(' или ');};
  const breath=t=>/backbend/.test(t)?['вдох','ровное дыхание']:/forward bend|twist/.test(t)?['выдох','ровное дыхание']:/inversion/.test(t)?['выдох','свободное дыхание']:['вдох','ровное дыхание'];
  const bySec={};
  for(const r of M.rows){const [n,si,en,sa,type,dr,mod,aka]=r;const L=LIB[n];if(!L)continue;
    const id='B'+n;JP[id]=L.jp;
    const tr=trType(type),dru=trDr(dr);
    DESC[id]=[L.note,tr?('Тип: '+tr+'.'):'',dru?('Взгляд: '+dru+'.'):'',`Д. Лакерда, «2100 Asanas», № ${n}.`].filter(Boolean).join(' ');
    const b=breath(type);const enOk=en&&!/^(Pose Type|\(|[a-z])/.test(en)&&en.length>3&&!/^(Prayer|Pose|Modification|Positions|Version 1)$/.test(en);const saOk=sa&&!/^Pose Type/.test(sa)?sa:'';
    (bySec[si]=bySec[si]||[]).push([`№${n}`,id,0,L.ru||en,[saOk,enOk?en:''].filter(Boolean).join(' · '),b[0],b[1],'',secRu[si]||M.secs[si][1]]);}
  const CH=['Стоя','Сидя','Кор','На четвереньках','Перевёрнутые','Лёжа на животе','Лёжа на спине'];
  for(const si in bySec){const sec=M.secs[si];const id='lib'+si;
    LIBSEQ[id]={id,name:secRu[si]||sec[1].toLowerCase(),chap:sec[0],chapName:CH[sec[0]],steps:bySec[si]};LIBSEC.push(id);}
})();
/* existing atlas poses whose old 2D-derived 3D shape was wrong: use the book-checked joint pose instead */
(function(){const OVR={x_gomukha:943,x_marichiA:802,x_pigeonfold:985,x_dhanura:1543,x_laghuvajra:1236,x_rajakap:979,x_matsyaclassic:1742,
  x_parshvottana:299,x_padang:191,x_ardhabaddha:147,garuda:149,parshvak:1333,x_astavakra:1330,tola:1293};
  for(const k in OVR)if(JP['B'+OVR[k]])JP[k]=JP['B'+OVR[k]];})();
/* pranamasana: palms together at the sternum, fingers up, forearms near horizontal, elbows relaxed out and down */
JP.pranam=mg({root:[0,0,90],hL:[0,3,4],hR:[0,3,4]},AP?arms('pr'):{});
/* ---------- Позы, исправленные по книге (аудит приложения) ----------
   Подставляются вместо поз атласа с тем же id (getPose берёт JP раньше P) и поверх поз библиотеки B<n>.
   Обозначения — как у библиотеки выше: root:[наклон,крен,поворот], pp — таз, sp/nk — позвоночник и шея,
   h/k/a — бедро/колено/стопа, s/e — плечо/локоть, tL/tR и gL/gR — цели кистей и стоп.
   KEEPYAW: при зеркале поза не разворачивается лицом в другую сторону (как позы атласа). */
(function(){
const K=window.KEEPYAW=window.KEEPYAW||{};
const def=(id,jp)=>{JP[id]=jp;K[id]=1;};
const T90={s:[0,90,0]};
/* ладонь на полу: цель кисти в системе ног (root) или груди, пальцы вперёд */
const PALM=(p,ref,pole)=>({p,ref:ref||'root',hd:[0,0,1],pn:[0,-1,0],pole:pole||[0.3,0,-1]});
const FLOOR={hm:{L:'floor',R:'floor'}};
const SHIN=(s,y,pole)=>({p:[0.02,y,0.03],ref:'ankle'+s,hd:[0,-1,0],pn:[1,0,0],pole:pole||[1,0,0]});
/* лотос «высоко»: колени подтянуты к груди — для поз на руках */
const LTL={p:[-0.12,0.12,0.22],ref:'root',pole:[1,0.6,0.6],fd:[1,0.3,0]}, LTR={p:[-0.12,0.15,0.20],ref:'root',pole:[1,0.6,0.6],fd:[1,0.3,0]};
const LOTUP={gL:LTL,gR:LTR,hL:[110,30,50],hR:[110,30,50]};

/* СС-62/71: прямые ноги вместе опущены вбок, стопы в 15–20 см над ладонью; руки в стороны; голова в другую сторону */
def('jathara',mg({root:[-90,-86,90],pp:[0,0,86],hL:[112,2,0],hR:[112,2,0],kL:0,kR:0,aL:10,aR:10,nk:[0,0,-65]},arms('T',T90)));

/* СС-76/77: стопа на колене прямой ноги, колено лежит на полу поперёк тела, кисть на колене, другая рука в сторону */
def('parivr',mg({root:[-90,80,90],pp:[0,0,-80],hL:[0,2,0],kL:0,aL:10,hR:[95,-12,0],kR:105,aR:-20,nk:[0,0,-60]},
  arm('R','T',T90),{tL:{p:[0,0.06,0.02],ref:'kneeR',hd:[0,-1,0],pn:[0,0,-1],pole:[1,0,0]}}));

/* СС-157, СТ-29: широкий наклон — ноги на две ширины плеч, макушка на полу, кисти держат голени */
const PRAS={hL:[0,32,8],hR:[0,32,8],pp:[118,0,0],sp:[50,0,0],nk:[35,0,0],aL:-5,aR:-5,c:['fL','fR']};
def('prasarita',mg(Y(90),PRAS,{tL:SHIN('L',0.22),tR:SHIN('R',0.22)}));
/* СТ-30: пирамидальное скручивание — рука за лодыжку другой ноги, вторая рука вверх, скручивание */
def('prasaritatw',mg(Y(90),PRAS,{sp:[38,0,55],nk:[25,0,30]},{tR:SHIN('L',0.08,[0,0,-1])},arm('L','T',{s:[10,85,0]})));

/* ЗСД-17…22: двойной лотосовый крест — руки из-за спины крест-накрест держат стопы той же стороны */
def('baddhapadma',mg(Y(0),{gL:GLL,gR:GLR,sp:[-8,0,0]},{
  tL:{p:[-0.22,0.0,-0.04],ref:'root',hd:[-1,0,0.3],pn:[0,0,1],pole:[0.4,0,-1]},
  tR:{p:[-0.22,0.0,-0.04],ref:'root',hd:[-1,0,0.3],pn:[0,0,1],pole:[0.4,0,-1]}}));
def('baddhafold',mg(JP.baddhapadma,{pp:[70,0,0],sp:[35,0,0],nk:[15,0,0]}));

/* ЗСД-48…50 и библиотека № 1293: весы — лотос на весу, опора на прямые руки у таза */
JP.B1293=mg(Y(60),LOTUP,{ab:1,pp:[30,0,0],sp:[10,0,0],nk:[-35,0,0],c:['hL','hR']},{tL:PALM([0.2,-0.19,0.08]),tR:PALM([0.2,-0.19,0.08])},FLOOR);
JP.tola=JP.B1293;K.tola=1;
/* СТ-20/21, ЗСД-46: верхний петух — лотос прижат к животу, руки прямые, кисти впереди, таз опущен */
def('kukkuta',mg(Y(70),LOTUP,{ab:1,pp:[40,0,0],sp:[10,0,0],nk:[-40,0,0],c:['hL','hR']},{tL:PALM([0.12,-0.2,0.24]),tR:PALM([0.12,-0.2,0.24])},FLOOR));
/* СТ-15: полное лотосовое скручивание в стойке на руках — таз завис над полом, лотос развёрнут вбок */
def('matsyendra',mg(Y(60),LOTUP,{ab:1,pp:[30,0,-35],sp:[10,0,-15],nk:[-25,0,-35],c:['hL','hR']},
  {tL:PALM([0.2,-0.22,0.12],'pelvis'),tR:PALM([0.24,-0.36,0.0],'pelvis')},FLOOR));
/* СС-54, ДС-30, ССД-63/64: собранный упор — колени к груди, стопы над полом, опора на прямые руки */
def('lola',mg(Y(90),{ab:1,hL:[120,6,0],hR:[120,6,0],kL:158,kR:158,aL:25,aR:25,pp:[40,0,0],sp:[25,0,0],nk:[-40,0,0],c:['hL','hR']},
  {tL:PALM([0.17,-0.3,0.32]),tR:PALM([0.17,-0.3,0.32])},FLOOR));
/* СКД-2: низкая стойка-сборка — колени у подмышек, руки слегка согнуты, стопы над полом */
def('bakadho',mg(Y(90),{ab:1,root:[80,0,0],hL:[145,24,0],hR:[145,24,0],kL:160,kR:160,aL:30,aR:30,sp:[25,0,0],nk:[-45,0,0],c:['hL','hR']},
  {tL:{p:[0.17,-0.12,0.42],ref:'chest',hd:[0,1,0],pn:[0,0,1],pole:[0,-1,0]},tR:{p:[0.17,-0.12,0.42],ref:'chest',hd:[0,1,0],pn:[0,0,1],pole:[0,-1,0]}},FLOOR));

/* СС-2: кузнечик — голова и плечи подняты, ладони впереди, прямые ноги назад-вверх */
def('shalabha',mg(Y(90),{root:[90,0,0],hL:[-15,4,0],hR:[-15,4,0],kL:0,kR:0,aL:-60,aR:-60,sp:[-40,0,0],nk:[-25,0,0]},{tL:{p:[0.17,0.78,0.12],ref:'root',hd:[0,1,0],pn:[0,0,1],pole:[1,0,0.5]},tR:{p:[0.17,0.78,0.12],ref:'root',hd:[0,1,0],pn:[0,0,1],pole:[1,0,0.5]}},FLOOR));

/* СТ-1…3: стойка всадника — стопы на 1,5–2 ширины плеч, параллельно */
def('horse',mg(Y(70),{hL:[12,22,-8],hR:[12,22,-8],kL:8,kR:8,aL:0,aR:0,pp:[12,0,0],sp:[-18,0,0],nk:[-10,0,0],c:['fL','fR']},arms('rpr')));
def('horse2',mg(Y(70),{hL:[14,22,-8],hR:[14,22,-8],kL:8,kR:8,pp:[15,0,0],sp:[-28,0,0],nk:[-15,0,0],c:['fL','fR']},arms('dn',{s:[25,8,0]})));
def('horse3',mg(Y(70),{hL:[28,22,-8],hR:[28,22,-8],kL:40,kR:40,aL:22,aR:22,pp:[10,0,0],sp:[-25,0,0],nk:[-20,0,0],c:['fL','fR']},arms('head')));

/* СС-10/12: поворот из змеиного прогиба — плечи и голова развёрнуты к пяткам, таз и ладони на месте */
const PRONEPALM=(x,y)=>({p:[x,y,0.12],ref:'root',hd:[0,1,0],pn:[0,0,1],pole:[0.4,0,-1]});
def('sarpturn',mg(Y(90),{root:[90,0,0],hL:[0,4,0],hR:[0,4,0],aL:-60,aR:-60,sp:[-50,0,38],nk:[-10,0,50]},{tL:PRONEPALM(0.2,0.42),tR:PRONEPALM(0.2,0.42)},FLOOR));
/* СС-31/32/36/37: поворот в широком упоре-прогибе — плечи и голова назад, к стопам; ноги и таз неподвижны */
const WUP={root:[86,0,0],hL:[0,8,0],hR:[0,8,0],aL:35,aR:35,pp:[-35,0,0],sp:[-12,0,0],nk:[-10,0,0],c:['hL','hR']};
const WUPH={tL:{p:[0.17,0.32,0.26],ref:'root',hd:[0,1,0],pn:[0,0,1],pole:[0.3,-1,0]},tR:{p:[0.17,0.32,0.26],ref:'root',hd:[0,1,0],pn:[0,0,1],pole:[0.3,-1,0]}};
def('wideup',mg(Y(90),WUP,WUPH,FLOOR));
def('wideupturn',mg(Y(90),WUP,{sp:[-12,0,40],nk:[-10,0,45]},WUPH,FLOOR));
/* СС-24 и кольца: полупрогиб в горизонтальном упоре — таз выше плеч, локти согнуты у рёбер, грудина низко */
def('ppchat',mg(Y(90),{root:[62,0,0],hL:[0,6,0],hR:[0,6,0],aL:30,aR:30,pp:[55,0,0],sp:[-28,0,0],nk:[-30,0,0],c:['hL','hR']},
  {tL:{p:[0.17,-0.22,0.22],ref:'chest',hd:[0,1,0],pn:[0,0,1],pole:[0.2,-1,0]},tR:{p:[0.17,-0.22,0.22],ref:'chest',hd:[0,1,0],pn:[0,0,1],pole:[0.2,-1,0]}},FLOOR));

/* СС-164: поперечные полуножницы с полупрогибом — кисти держат большие пальцы ног, грудь вперёд-вверх */
const TOE=(s)=>({p:[0,-0.03,0.15],ref:'ankle'+s,hd:[0,0,1],pn:[1,0,0],pole:[0,-1,0]});
def('upavup',mg(Y(0),{hL:[88,35,0],hR:[88,35,0],kL:0,kR:0,aL:10,aR:10,pp:[45,0,0],sp:[-12,0,0],nk:[-15,0,0]},{tL:TOE('L'),tR:TOE('R')}));
/* СС-108: угловое вытягивание — лёжа на спине, прямые ноги за вертикаль, кисти на больших пальцах */
def('angstr',mg({root:[-90,0,90],hL:[128,10,0],hR:[128,10,0],kL:0,kR:0,aL:10,aR:10},{tL:TOE('L'),tR:TOE('R')}));

/* СС-264…269: «медвежий замок» — кисти соединены между лопатками, верхний локоть вверх.
   bearbend — наклон в сторону верхней руки, bearbend2 — в другую; m=0 — правая рука сверху. */
const BEAR={tR:{p:[0.0,-0.13,-0.15],ref:'chest',hd:[0,-1,0],pn:[0,0,-1],pole:[0.3,1,-0.2]},tL:{p:[0.0,-0.22,-0.15],ref:'chest',hd:[0,1,0],pn:[0,0,-1],pole:[0.3,-1,-0.2]}};
def('bearbend',mg(Y(15),ST,{sp:[0,-30,0],nk:[0,-10,0]},BEAR));
def('bearbend2',mg(Y(15),ST,{sp:[0,30,0],nk:[0,10,0]},BEAR));
def('bearfold',mg(Y(70),ST,{pp:[95,0,0],sp:[35,0,0],nk:[20,0,0]},BEAR));

/* ЛК-40/70: верхний полуверблюд — на колене и одной ладони, поднятая нога сзади, рука той же стороны держит лодыжку */
const ANK=(s,pole)=>({p:[0,0.05,0],ref:'ankle'+s,hd:[0,-1,0],pn:[-1,0,0],pole:pole||[0,-1,0]});
const TABP=(s)=>({['t'+s]:PALM([0.17,-0.45,0.55]),hm:{[s]:'floor'}});
def('polverb',mg(Y(90),TAB({hR:[-60,4,0],kR:135,aR:-40,sp:[-40,0,0],nk:[-35,0,0]}),{tR:ANK('R')},TABP('L'),{C:['hL']}));
/* ЛК-45/75: перекрёстный — лодыжку держит противоположная рука */
def('crossverb',mg(Y(90),TAB({hR:[-60,4,0],kR:135,aR:-40,sp:[-30,0,-30],nk:[-30,0,-20]}),{tL:ANK('R')},TABP('R'),{C:['hR']}));
/* ЛКД-1/3: вытянутый верхний верблюд — кисть под стопой снаружи, локоть вверх */
def('verb1',mg(Y(90),TAB({hR:[-95,4,0],kR:140,aR:-30,sp:[-50,0,0],nk:[-40,0,0]}),{tR:ANK('R',[0,1,0])},TABP('L'),{C:['hL']}));
def('cverb1',mg(Y(90),TAB({hR:[-95,4,0],kR:140,aR:-30,sp:[-45,0,-25],nk:[-40,0,-15]}),{tL:ANK('R',[0,1,0])},TABP('R'),{C:['hR']}));
/* СКД-17: кольцо в широком шаге — колено задней ноги на полу, стопа к макушке, рука той же стороны из-за головы держит стопу,
   другая ладонь на полу у передней стопы. СКД-21 — стопу держит противоположная рука. */
const RING={hR:[88,6,0],kR:95,aR:10,hL:[-30,4,0],kL:160,aL:-50,pp:[-5,0,0],sp:[-55,0,0],nk:[-45,0,0],c:['fR']};
def('ring1',mg(Y(90),RING,{tL:ANK('L',[0,1,0])},{tR:{p:[0.03,0.06,0.02],ref:'kneeR',hd:[0,0,1],pn:[0,-1,0],pole:[1,0,-1]}}));
def('cring1',mg(Y(90),RING,{hL:[-20,-10,0],sp:[-45,0,-60],nk:[-35,0,-30]},{tR:ANK('L',[0,1,0])},{tL:{p:[-0.03,0.06,0.02],ref:'kneeR',hd:[0,0,1],pn:[0,-1,0],pole:[1,0,-1]}}));
/* СКД-24: предельное растягивание бедра с прогибом — кисть той же стороны прижимает заднюю стопу к тазу, другая рука упирается в переднее бедро */
def('quadbend',mg(Y(90),{hR:[85,6,0],kR:95,aR:10,hL:[-25,4,0],kL:160,aL:-50,pp:[-5,0,0],sp:[-28,0,0],nk:[-30,0,0],c:['fR']},
  {tL:ANK('L',[0,0,-1])},{tR:{p:[0.05,-0.18,0.03],ref:'hipR',hd:[0,-1,0],pn:[0,0,-1],pole:[1,0,-1]}}));

/* библиотека: петух (№ 1292) — как верхний петух; полулотос в позе бесконечности (№ 826, 827, 861) — на правом боку */
JP.B1292=mg(JP.kukkuta,Y(60));
/* стрекоза (№ 1317) и Аштавакра (№ 1330): ноги вбок — крен таза и обратная скрутка груди, как у Каундиньи */
for(const n of [1317,1330]){const j=JP['B'+n];if(j)JP['B'+n]={...j,root:[85,85,(j.root||[0,0,0])[2]],pp:[0,0,85]};}
for(const n of [826,827,861]){const j=JP['B'+n];if(j&&j.root)JP['B'+n]={...j,root:[j.root[0],-(j.root[1]||0),j.root[2]]};}
})();


